import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent

def add_time_read(w):
    d=json.loads((ROOT/'results.json').read_text(encoding='utf8')); c=d['costs']
    available=d['label_available']; competitive=d['available_5plus']
    w.page('Чтение исторической памяти   /   99 задач Lite','Кого читатель выбирает из допустимых записей',
           'На дату открытия каждого запроса собрана отдельная библиотека. Источник — другой PR того же репозитория, влитый строго раньше отсечения. При пустой выдаче система воздерживалась. Единственную запись принимала без генерации. При наличии конкурентов Qwen выбирала одну из первых пяти историй.')
    methods=[('recent_1','Самый свежий PR'),('online_fields_1','BM25 по трём полям, только прошлое'),('online_fields_qwen','Тот же BM25 + Qwen'),('hyb_real_1','Гибридный поиск, отфильтрованный¹'),('hyb_real_qwen','Тот же гибридный поиск + Qwen'),('online_fields_5','Связь в списке из пяти BM25'),('hyb_real_5','Связь в списке из пяти гибрида')]
    data=[[name,str(d['all']['hits'][m])+'/99',str(available['hits'][m])+'/'+str(available['n']),str(competitive['hits'][m])+'/'+str(competitive['n'])] for m,name in methods]
    w.tbl(['Метод','Все','Метка доступна','Метка и ≥5 записей'],data,[7.8,2.3,3.2,3.8],True)
    w.p(f"¹ Векторные ранги и корпусные статистики гибрида исходно рассчитаны на всей статической библиотеке. У варианта BM25 частоты и длины рассчитаны заново только по допустимым записям. Для равномерного выбора из разрешённой библиотеки ожидается {d['all']['chance_expected_hits']:.2f} попадания на 99 запросов. Условная группа с ≥5 записями содержит {competitive['distinct_pr']} разных PR.",'Caption')
    w.p(f"Пустая библиотека у {c['empty']} запросов, одна запись у {c['singleton']}. Два сравниваемых читателя в сумме выполнили {c['actual_calls']} различных запросов к локальной Qwen3.8-27B. При дословном совпадении подсказки и параметров единственный ответ использован в обоих условиях. Фактический расход после такого объединения — {c['input']:,} входных и {c['output']:,} выходных токенов.".replace(',',' '))
    w.p('Значение на всём наборе включает отсутствие размеченного предшественника. В условном столбце остаются и очень лёгкие случаи с единственной подходящей записью. Даже среди доступных записей авторские метки покрывают лишь опубликованные связи. По этим числам нельзя определить, помогла ли другая найденная история решить задачу.')
    w.source('Исходные задачи и авторские связи SWE-ContextBench','https://huggingface.co/datasets/jiayuanz3/SWEContextBench/tree/12c65bd15e2559bc808065565e941ee7bbbd008f')

